/* Deterministic geometric sources. Gray–Scott snapshots are computed offline;
   no simulation, random generator, or animation clock runs in a render call. */
(() => {
  'use strict';
  const phi = (1 + Math.sqrt(5)) / 2;
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  function phyllotaxis(count, radius = 1, rotation = 0) {
    return Array.from({length: count}, (_, i) => {
      const r = radius * Math.sqrt(i / Math.max(1, count - 1));
      const a = i * goldenAngle + rotation;
      return {x: Math.cos(a) * r, y: Math.sin(a) * r};
    });
  }

  // A point belongs to site i iff it lies on i's side of every perpendicular
  // bisector. Sutherland–Hodgman clipping gives exact convex Voronoi polygons.
  function voronoi(points, bounds = [-1, -1, 1, 1]) {
    return points.map((site, i) => {
      let polygon = [
        {x: bounds[0], y: bounds[1]}, {x: bounds[2], y: bounds[1]},
        {x: bounds[2], y: bounds[3]}, {x: bounds[0], y: bounds[3]}
      ];
      for (let j = 0; j < points.length && polygon.length; j++) {
        if (i === j) continue;
        const other = points[j], nx = other.x - site.x, ny = other.y - site.y;
        const c = (other.x * other.x + other.y * other.y - site.x * site.x - site.y * site.y) / 2;
        const clipped = [];
        for (let k = 0; k < polygon.length; k++) {
          const a = polygon[k], b = polygon[(k + 1) % polygon.length];
          const da = a.x * nx + a.y * ny - c, db = b.x * nx + b.y * ny - c;
          if (da <= 1e-9) clipped.push(a);
          if ((da < 0) !== (db < 0)) {
            const t = da / (da - db);
            clipped.push({x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t});
          }
        }
        polygon = clipped;
      }
      return {site, polygon};
    });
  }
  const sites = phyllotaxis(89);
  const cells = voronoi(sites);

  // Each column is an attractor sample of x[n+1] = r*x[n]*(1-x[n]).
  // 700 transient generations are discarded; 120 subsequent values are kept.
  const bifurcation = Array.from({length: 560}, (_, i) => {
    const r = 2.8 + (i / 559) * 1.2;
    let x = 0.3141592653589793;
    for (let j = 0; j < 700; j++) x = r * x * (1 - x);
    const values = new Float32Array(120);
    for (let j = 0; j < values.length; j++) { x = r * x * (1 - x); values[j] = x; }
    return {r, values};
  });

  // 96 x 96, periodic boundary conditions, source nine-point Laplacian:
  // center -1, axial .2, diagonal .05. Da=1, Db=.5, F=.0545, K=.062,
  // dt=1. Deterministic phyllotaxis seeds; one bit per B > .18 pixel.
  const reactionSize = 96;
  const reactionSteps = [0,7,13,20,27,33,40,50,60,70,80,90,100,113,127,140,153,167,180,197,213,230,247,263,280,300,320,340,360,380,400,425,450,475,500,525,550,575,600,625,650,675,700,725,750,775,800,825,850,875,900,925,950,975,1000,1033,1067,1100,1133,1167,1200,1260,1320,1380,1440,1500,1560,1620,1680,1740,1800,1880,1960,2040,2120,2200,2280,2360,2440,2520,2600,2680,2760,2840,2920,3000,3080,3160,3240,3320,3400,3520,3640,3760,3880,4000];
  const reactionData = ["","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""];
  const reactionCache = new Map();
  function reactionState(progress) {
    const index = Math.min(reactionSteps.length - 1, Math.max(0, Math.round(progress * (reactionSteps.length - 1))));
    return {index, iteration: reactionSteps[index]};
  }
  function reactionFrame(progress, ink = '#0A0A0A', paper = '#FFD400') {
    const {index} = reactionState(progress);
    const key = index + ':' + ink + ':' + paper;
    if (reactionCache.has(key)) return reactionCache.get(key);
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = reactionSize;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = paper; ctx.fillRect(0, 0, reactionSize, reactionSize);
    ctx.fillStyle = ink;
    const bytes = atob(reactionData[index]);
    for (let i = 0; i < reactionSize * reactionSize; i++) {
      if ((bytes.charCodeAt(i >> 3) >> (i & 7)) & 1) ctx.fillRect(i % reactionSize, Math.floor(i / reactionSize), 1, 1);
    }
    // Keep at most 16 decoded 96px canvases, even after a full forward/reverse pass.
    if (reactionCache.size >= 16) reactionCache.delete(reactionCache.keys().next().value);
    reactionCache.set(key, canvas);
    return canvas;
  }
  WTE.patterns = {phi, goldenAngle, phyllotaxis, voronoi, sites, cells,
    bifurcation, reactionFrame, reactionState, reactionSteps, reactionSize,
    reactionModel: {feed: .0545, kill: .062, diffusionA: 1, diffusionB: .5, threshold: .18}};
})();
